'use client';
import { useEffect, useRef } from 'react';
export default function Template({children}:{children:React.ReactNode}) {
  const root = useRef<HTMLDivElement>(null);
  useEffect(() => {
    if(window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
    const observer = new IntersectionObserver(entries => entries.forEach(entry => { if(entry.isIntersecting) { entry.target.classList.add('revealed'); observer.unobserve(entry.target); } }), {threshold:.08});
    root.current?.querySelectorAll('.intro-section,.pillar,.technology-inner,.article-card,.careers-invitation,.content-section').forEach(node => { if(node.getBoundingClientRect().top > window.innerHeight) { node.classList.add('reveal-pending'); observer.observe(node); } });
    return () => observer.disconnect();
  },[]);
  return <div ref={root} className="page-transition">{children}</div>;
}
